import { PackageManagerTabs } from "@rspress/core/theme-original";

type Commands = {
  npm: string;
  pnpm: string;
  yarn: string;
  bun: string;
};

/**
 * Generated by `scripts/remark-package-manager.ts` from an `npm` code fence.
 * The commands arrive as JSON so the remark plugin can build the MDX element
 * without constructing a JavaScript expression AST.
 */
export function PackageManagerCommands({ commands }: { commands: string }) {
  return <PackageManagerTabs command={JSON.parse(commands) as Commands} />;
}

export default PackageManagerCommands;
